import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/chat/message_model.dart';
import '../models/chat/conversation_model.dart';
class ChatRepository { ChatRepository(this._db); final FirebaseFirestore _db; Stream<List<ConversationModel>> watchConversations(String userId)=>_db.collection('conversations').where('participantIds',arrayContains:userId).orderBy('updatedAt',descending:true).snapshots().map((s)=>s.docs.map(ConversationModel.fromFirestore).toList()); Stream<List<MessageModel>> watchMessages(String id)=>_db.collection('conversations').doc(id).collection('messages').orderBy('createdAt').snapshots().map((s)=>s.docs.map(MessageModel.fromFirestore).toList()); Future<void> send(MessageModel message) async { final conversation=_db.collection('conversations').doc(message.conversationId); final batch=_db.batch(); batch.set(conversation,{'participantIds':FieldValue.arrayUnion([message.senderId,if(message.receiverId!=null)message.receiverId]),'lastMessage':message.text,'updatedAt':FieldValue.serverTimestamp(),'typingUserIds':FieldValue.arrayRemove([message.senderId])},SetOptions(merge:true)); batch.set(conversation.collection('messages').doc(message.id),message.toMap()); await batch.commit(); } Future<void> setTyping(String conversationId,String userId,bool isTyping)=>_db.collection('conversations').doc(conversationId).set({'typingUserIds':isTyping?FieldValue.arrayUnion([userId]):FieldValue.arrayRemove([userId]),'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true)); Future<void> markRead(String conversationId,String userId)=>_db.collection('conversations').doc(conversationId).set({'unreadCounts.$userId':0},SetOptions(merge:true)); Future<void> delete(String conversationId,String messageId)=>_db.collection('conversations').doc(conversationId).collection('messages').doc(messageId).update({'isDeleted':true,'text':'','updatedAt':FieldValue.serverTimestamp()}); Future<void> toggleReaction({required String conversationId,required String messageId,required String userId,required String emoji}) async {final ref=_db.collection('conversations').doc(conversationId).collection('messages').doc(messageId).collection('reactions').doc(userId); final old=await ref.get(); if(old.exists && old.data()?['emoji']==emoji){await ref.delete();}else{await ref.set({'userId':userId,'emoji':emoji,'createdAt':FieldValue.serverTimestamp()});}} }
